<script setup lang="ts">
import {computed} from 'vue';
import {identityProviderLabel, identityStatusLabel, type IdentityReview} from '../api/identity';
const props = defineProps<{review: IdentityReview; selected: boolean; disabled?: boolean}>();
const emit = defineEmits<{toggle: []}>();
const confidence = computed(() => Number.isFinite(props.review.identification.confidence) ? `${Math.round(Math.max(0, Math.min(1, props.review.identification.confidence)) * 100)}%` : '未知');
</script>
<template><article class="identity-card">
<div class="review-title"><label v-if="review.status==='pending'"><input type="checkbox" :checked="selected" :disabled="disabled" :aria-label="'选择候选 #'+review.id" @change="emit('toggle')">候选 #{{review.id}}</label><strong v-else>候选 #{{review.id}}</strong><span>{{review.status==='pending'?'待审核':identityStatusLabel(review.status)}}</span></div>
<div class="comparison"><section><h3>当前资料</h3><dl><dt>书名</dt><dd>{{review.before.title||'未填写'}}</dd><dt>作者</dt><dd>{{review.before.author||'未填写'}}</dd><dt>系列</dt><dd>{{review.before.series_name||'无'}}</dd><dt>卷号</dt><dd>{{review.before.volume_label||'无'}}</dd><dt>封面</dt><dd>{{review.before.has_cover?'已有封面':'无封面'}}</dd></dl><details v-if="review.before.description"><summary>当前简介</summary><p>{{review.before.description}}</p></details></section>
<section><h3>建议资料</h3><dl><dt>书名</dt><dd class="suggested-title">{{review.candidate.title||'未识别'}}</dd><dt>作者</dt><dd>{{review.candidate.author||'未识别'}}</dd><dt>系列</dt><dd>{{review.candidate.series||'无'}}</dd><dt>卷号</dt><dd>{{review.candidate.volume_label||'无'}}</dd><dt>封面</dt><dd>{{review.candidate.has_cover?'候选有封面':review.before.has_cover?'保留现有封面':'未找到可靠封面'}}</dd></dl><details v-if="review.candidate.description"><summary>建议简介</summary><p>{{review.candidate.description}}</p></details></section></div>
<div class="evidence"><h3>内容识别依据</h3><p>整书名：{{review.identification.work_title||'未识别'}} · 信心 {{confidence}}</p><p v-if="review.identification.part_title||review.identification.part_label">分篇：{{review.identification.part_title||'未命名'}} · {{review.identification.part_label||('第'+review.identification.part_number+'篇')}}<span v-if="review.identification.part_number"> · 序号 {{review.identification.part_number}}</span></p><p v-if="review.identification.reason">{{review.identification.reason}}</p><blockquote v-if="review.identification.evidence">{{review.identification.evidence}}</blockquote><ul v-if="review.sources.length"><li v-for="(source,index) in review.sources" :key="index">{{identityProviderLabel(source.provider)}} · {{identityStatusLabel(source.status)}}<template v-if="source.note"> · {{source.note}}</template></li></ul><p v-if="review.status==='pending'&&!review.can_apply" class="error">候选已失效或当前无应用权限，保留待核对；请检查资料与权限后重新识别，或拒绝此候选。</p></div>
</article></template>
<style scoped>
.identity-card{border:1px solid var(--border);border-radius:12px;padding:16px;margin:14px 0;min-width:0;overflow-wrap:anywhere}.review-title{display:flex;justify-content:space-between;gap:12px;align-items:center}.review-title label{display:inline-flex;align-items:center;gap:8px;font-weight:600}.review-title input{width:18px;height:18px}.review-title span{font-size:13px;color:var(--muted)}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:12px}.comparison section{min-width:0}.identity-card h3{font-size:14px;margin:8px 0}.comparison dl{display:grid;grid-template-columns:3em 1fr;gap:6px 10px;font-size:14px;margin:10px 0}.comparison dt{color:var(--muted)}.comparison dd{margin:0}.suggested-title{color:var(--accent);font-weight:600}.identity-card p,.identity-card li,.identity-card summary{font-size:13px;line-height:1.7}.evidence{border-top:1px solid var(--border);margin-top:14px;padding-top:10px}.evidence blockquote{margin:10px 0;border-left:3px solid var(--accent);background:var(--bg);padding:10px 12px;font-size:14px;white-space:pre-wrap}.evidence ul{padding-left:20px;margin:8px 0}.identity-card details p{white-space:pre-wrap}@media(max-width:500px){.comparison{grid-template-columns:1fr;gap:10px}.comparison section+section{border-top:1px dashed var(--border);padding-top:6px}.identity-card{padding:12px}}
</style>
